type PageMessageType = typeof pageMessage_pt;
const pageMessages: { [key: string]: PageMessageType } = { 'pt': pageMessage_pt };
/// **collab_i18n_end**

function errorText(error: ErrorState, msg: PageMessageType): string {
  if (!error) return '';
  const client: Record<string, string> = {
    'client.requiredMissing': msg['error.requiredMissing'],
    'client.preconditionMissing': msg['error.preconditionMissing'],
    'client.snapshotMissing': msg['error.snapshotMissing'],
    'client.selectionInvalid': msg['error.selectionInvalid'],
    'client.unexpected': msg['error.unexpected'],
  };
  return client[error.code] ?? (error.message || msg['error.unexpected']);
}

function formatNumber(value: number): string {
  return new Intl.NumberFormat(document.documentElement.lang || undefined).format(value);
}

@customElement('controle-estoque--web--desktop--page11--produtos-102047')
export class ControleEstoqueDesktopPage11ProdutosPage extends ControleEstoqueProdutosShared {
  private msg: PageMessageType = pageMessage_pt;

  render() {
    this.msg = pageMessages[this.getMessageKey(pageMessages)];
    // scenes: base — the overview and the product list with its detail beside it are what the estoquista checks on arrival; cadastro — registering a product is a task of its own, opened by a button
    return html`
      <main class="min-h-full bg-[var(--page-bg,transparent)] text-[var(--text-default,currentColor)]">
        <div class="mx-auto w-full max-w-6xl px-4 py-6 space-y-6">
          <h1 class="text-2xl font-semibold text-[var(--text-strong,currentColor)]">${this.msg['page.title']}</h1>
          ${this.renderLoadError()}
          <molecules--ml-scenary-102020 mode="scenary" .value=${this.scenary || 'base'} backLabel=${this.msg['scene.back']}
            @change=${(e: CustomEvent<{ value: string }>) => { if (e.target === e.currentTarget) this.setScenario(e.detail.value); }}>
            <Scene value="base" title=${this.msg['scene.base']}>${this.renderSceneBase()}</Scene>
            <Scene value="cadastro" title=${this.msg['scene.cadastro']} nav="back">${this.renderSceneCadastro()}</Scene>
          </molecules--ml-scenary-102020>
        </div>
      </main>`;
  }

  renderSceneBase() {
    return html`
      <div class="space-y-6">
        <div class="flex justify-end">
          <grouptriggeraction--ml-button-standard data-variant="primary" @action=${() => this.setScenario('cadastro')}>
            <Label>${this.msg['cadastro.open']}</Label>
          </grouptriggeraction--ml-button-standard>
        </div>
        <section data-section-id="visaoGeral" class="grid grid-cols-1 gap-4 lg:grid-cols-[minmax(0,2fr)_minmax(0,1fr)]">
          <h2 class="sr-only">${this.msg['visaoGeral.title']}</h2>
          ${this.renderSaldoAtual()}
          ${this.renderAlertasSaldoBaixo()}
        </section>
        <section data-section-id="consulta" class="grid grid-cols-1 gap-4 lg:grid-cols-[minmax(0,2fr)_minmax(0,1fr)]">
          <h2 class="sr-only">${this.msg['consulta.title']}</h2>
          ${this.renderListaProdutos()}
          ${this.renderDetalheProduto()}
        </section>
      </div>`;
  }

  renderSceneCadastro() {
    return html`
      <section data-section-id="cadastro" class="rounded-lg border border-[var(--border-default,currentColor)] bg-[var(--surface-bg,transparent)] p-4 space-y-4">
        <h2 class="text-lg font-semibold text-[var(--text-strong,currentColor)]">${this.msg['cadastro.title']}</h2>
        ${this.renderFormularioProduto()}
        ${this.renderAcoesCadastro()}
      </section>`;
  }

  renderLoadError() {
    if (!this.loadError) return nothing;
    return html`
      <div role="alert" class="rounded-lg px-4 py-3 bg-[var(--status-error-bg,transparent)] text-[var(--status-error-text,currentColor)] flex items-center justify-between gap-4">
        <span>${errorText(this.loadError, this.msg)}</span>
        <grouptriggeraction--ml-button-standard data-variant="secondary" size="sm" @action=${() => this.load()}>
          <Label>${this.msg['error.retry']}</Label>
        </grouptriggeraction--ml-button-standard>
      </div>`;
  }

  renderSaldoAtual() {
    return html`
      <div data-organism-id="saldoAtual" class="min-w-0">
        <groupviewtable--ml-data-table .loading=${this.pageStatus === 'loading'}>
          <TableHeader>
            <TableRow>
              <TableHead key="name">${this.msg['saldo.col.name']}</TableHead>
              <TableHead key="unit">${this.msg['saldo.col.unit']}</TableHead>
              <TableHead key="balance">${this.msg['saldo.col.balance']}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            ${this.saldoAtual.map(item => html`
              <TableRow key=${item.id}>
                <TableCell>${item.details.identification.name}</TableCell>
                <TableCell>${item.details.product.unitOfMeasure}</TableCell>
                <TableCell sort-value=${String(item.details.controleEstoque.saldoAtual)}>${formatNumber(item.details.controleEstoque.saldoAtual)}</TableCell>
              </TableRow>`)}
          </TableBody>
          <Empty>${this.msg['saldo.empty']}</Empty>
        </groupviewtable--ml-data-table>
      </div>`;
  }

  renderAlertasSaldoBaixo() {
    return html`
      <div data-organism-id="alertasSaldoBaixo" class="min-w-0 space-y-2">
        <h3 class="text-sm font-medium text-[var(--text-muted,currentColor)]">${this.msg['alertas.title']}</h3>
        <groupviewdata--ml-card-grid .selectable=${true}
          @row-click=${(e: CustomEvent<{ index: number }>) => this.selecionarProduto(this.alertasSaldoBaixo[e.detail.index]?.id ?? null)}>
          <Columns>
            <Column field="name" header=${this.msg['alertas.col.name']}></Column>
            <Column field="balance" header=${this.msg['alertas.col.balance']}></Column>
            <Column field="minimum" header=${this.msg['alertas.col.minimum']}></Column>
          </Columns>
          <Rows>
            ${this.alertasSaldoBaixo.map(item => html`
              <Row ?selected=${item.id === this.produtoSelecionado}>
                <Cell>${item.details.identification.name}</Cell>
                <Cell>${formatNumber(item.details.controleEstoque.saldoAtual)}</Cell>
                <Cell>${formatNumber(item.details.controleEstoque.quantidadeMinima)}</Cell>
              </Row>`)}
          </Rows>
          <Empty>${this.msg['alertas.empty']}</Empty>
        </groupviewdata--ml-card-grid>
      </div>`;
  }

  renderListaProdutos() {
    const statusLabel = (item: ProdutoLoad) => this.msg[`status.${item.details.identification.status}` as keyof PageMessageType] ?? item.details.identification.status;
    const selectedIndex = this.listaProdutos.findIndex(item => item.id === this.produtoSelecionado);
    return html`
      <div data-organism-id="listaProdutos" class="min-w-0 space-y-3">
        <groupsearchcontent--ml-search-bar .value=${this.filtroBuscaProdutos} placeholder=${this.msg['lista.search.placeholder']}
          @change=${(e: CustomEvent<{ value: string | null }>) => this.filterListaProdutos(e.detail.value)}
          @clear=${() => this.filterListaProdutos(null)}>
          <Label>${this.msg['lista.search.label']}</Label>
        </groupsearchcontent--ml-search-bar>
        <groupviewtable--ml-data-table .loading=${this.loadStatus === 'loading'} value=${selectedIndex < 0 ? '' : String(selectedIndex)}
          @rowClick=${(e: CustomEvent<{ index: number }>) => this.selecionarProduto(this.listaProdutos[e.detail.index]?.id ?? null)}>
          <TableHeader>
            <TableRow>
              <TableHead key="name">${this.msg['lista.col.name']}</TableHead>
              <TableHead key="status">${this.msg['lista.col.status']}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            ${this.listaProdutos.map(item => html`
              <TableRow key=${item.id}>
                <TableCell>${item.details.identification.name}</TableCell>
                <TableCell>${statusLabel(item)}</TableCell>
              </TableRow>`)}
          </TableBody>
          <Empty>${this.msg['lista.empty']}</Empty>
          <Loading>${this.msg['lista.loading']}</Loading>
        </groupviewtable--ml-data-table>
        ${this.listaProdutosHasMore ? html`
          <grouptriggeraction--ml-button-standard data-variant="secondary" size="sm" .loading=${this.loadStatus === 'loading'}
            @action=${() => this.loadMoreListaProdutos()}>
            <Label>${this.msg['lista.loadMore']}</Label>
          </grouptriggeraction--ml-button-standard>` : nothing}
      </div>`;
  }

  renderDetalheProduto() {
    const item = this.detalheProduto;
    return html`
      <div data-organism-id="detalheProduto" class="min-w-0">
        ${item ? html`
          <groupviewcard--ml-vertical-card>
            <CardHeader>
              <CardTitle>${item.details.identification.name}</CardTitle>
              <CardDescription>${this.msg['detalhe.unit']}: ${item.details.product.unitOfMeasure}</CardDescription>
            </CardHeader>
            <CardContent>
              <div class="grid grid-cols-2 gap-3">
                <groupviewmetric--ml-metric-card>
                  <Label>${this.msg['detalhe.balance']}</Label>
                  <Value>${formatNumber(item.details.controleEstoque.saldoAtual)}</Value>
                  ${item.details.controleEstoque.saldoAbaixoDoMinimo ? html`<Helper>${this.msg['detalhe.belowMinimum']}</Helper>` : nothing}
                </groupviewmetric--ml-metric-card>
                <groupviewmetric--ml-metric-card>
                  <Label>${this.msg['detalhe.minimum']}</Label>
                  <Value>${formatNumber(item.details.controleEstoque.quantidadeMinima)}</Value>
                </groupviewmetric--ml-metric-card>
              </div>
            </CardContent>
            <CardFooter>
              <grouptriggeraction--ml-button-standard data-variant="primary" @action=${() => this.abrirMovimentacoes()}>
                <Label>${this.msg['detalhe.openMovements']}</Label>
              </grouptriggeraction--ml-button-standard>
            </CardFooter>
          </groupviewcard--ml-vertical-card>` : html`
          <p role="status" class="rounded-lg border border-[var(--border-subtle,currentColor)] p-4 text-sm text-[var(--text-muted,currentColor)]">${this.msg['detalhe.empty']}</p>`}
      </div>`;
  }

  renderFormularioProduto() {
    const draft = this.produtoCadastro;
    return html`
      <div data-organism-id="formularioProduto" class="grid grid-cols-1 gap-4 md:grid-cols-3">
        <groupentertext--ml-enter-text .value=${draft.details.identification.name ?? ''} required
          @change=${(e: CustomEvent<{ value: string }>) => this.setProdutoCadastro({ details: { ...draft.details, identification: { name: e.detail.value || null } } })}>
          <Label>${this.msg['form.name']}</Label>
        </groupentertext--ml-enter-text>
        <groupentertext--ml-enter-text .value=${draft.details.product.unitOfMeasure ?? ''} required
          @change=${(e: CustomEvent<{ value: string }>) => this.setProdutoCadastro({ details: { ...draft.details, product: { unitOfMeasure: e.detail.value || null } } })}>
          <Label>${this.msg['form.unit']}</Label>
        </groupentertext--ml-enter-text>
        <groupenternumber--ml-number-input .value=${draft.details.controleEstoque.quantidadeMinima} .min=${0} required
          @change=${(e: CustomEvent<{ value: number | null }>) => this.setProdutoCadastro({ details: { ...draft.details, controleEstoque: { quantidadeMinima: e.detail.value } } })}>
          <Label>${this.msg['form.minimum']}</Label>
        </groupenternumber--ml-number-input>
      </div>`;
  }

  renderAcoesCadastro() {
    return html`
      <div data-organism-id="acoesCadastro" class="flex flex-wrap items-center gap-3">
        <grouptriggeraction--ml-button-standard data-variant="primary" .loading=${this.cadastrarProdutoStatus === 'loading'}
          @action=${() => this.cadastrarProduto()}>
          <Label>${this.msg['form.submit']}</Label>
        </grouptriggeraction--ml-button-standard>
        ${this.cadastrarProdutoError ? html`<p role="alert" class="text-sm text-[var(--status-error-text,currentColor)]">${errorText(this.cadastrarProdutoError, this.msg)}</p>` : nothing}
        ${this.cadastrarProdutoStatus === 'success' ? html`<p role="status" aria-live="polite" class="text-sm text-[var(--status-success-text,currentColor)]">${this.msg['form.saved']}</p>` : nothing}
      </div>`;
  }
}

